import { buildEngModel } from '../models/buildEngModel';
import { calcNeutralPoint } from './calcNeutralPoint';
import { analyzeJarPlacement } from '../jar/jarAnalysis';

// Independent arithmetic reference: these expectations are not generated by the production functions.
const BF = 1 - 10 / 65.5;
const row = (category, length, weight) => ({ category, toolName: category, length, weight, od: 8 });
const bha = rows => ({ rows, wob: 30, mudWeight: 10, holeSize: 12.25 });
const near = (actual, expected) => expect(actual).toBeCloseTo(expected, 5);

describe('vertical static axial-load baseline (compression positive)', () => {
  test('case 1: one collar, force boundary and neutral point', () => {
    const model = buildEngModel(bha([row('DC', 200, 200)]));
    near(model.positions.components[0].airWeight, 40000);
    near(model.positions.components[0].buoyedWeight, 40000 * BF);
    near(model.axialLoads.bitAxialForce, 30000);
    near(model.axialLoads.topOfBhaAxialForce, 30000 - 40000 * BF);
    near(calcNeutralPoint(model).neutralPointFromBit, 30000 / (200 * BF));
  });

  test('case 2: jar below neutral point and multicomponent boundary forces', () => {
    const assembly = bha([row('DC', 100, 200), row('JAR', 30, 150), row('DC', 100, 200)]);
    const model = buildEngModel(assembly);
    const expectedJarBottom = 30000 - 20000 * BF;
    const expectedJarTop = expectedJarBottom - 4500 * BF;
    near(model.axialLoads.components[1].bottomAxialForce, expectedJarBottom);
    near(model.axialLoads.components[1].topAxialForce, expectedJarTop);
    near(model.axialLoads.topOfBhaAxialForce, 30000 - 44500 * BF);
    near(calcNeutralPoint(model).neutralPointFromBit, 130 + expectedJarTop / (200 * BF));
    const result = analyzeJarPlacement(assembly);
    expect(result.jars).toHaveLength(1);
    near(result.jars[0].startFt, 100);
    near(result.jars[0].endFt, 130);
    expect(result.jars[0].issues.some(s => s.includes('inside jar'))).toBe(false);
  });

  test('case 3: neutral point inside jar triggers warning', () => {
    const assembly = bha([row('DC', 160, 200), row('JAR', 30, 150), row('DC', 40, 200)]);
    const model = buildEngModel(assembly);
    const expectedJarBottom = 30000 - 32000 * BF;
    const expectedJarTop = expectedJarBottom - 4500 * BF;
    near(model.axialLoads.components[1].bottomAxialForce, expectedJarBottom);
    near(model.axialLoads.components[1].topAxialForce, expectedJarTop);
    expect(expectedJarBottom).toBeGreaterThan(0);
    expect(expectedJarTop).toBeLessThan(0);
    const expectedNeutral = 160 + expectedJarBottom / (150 * BF);
    near(calcNeutralPoint(model).neutralPointFromBit, expectedNeutral);
    const result = analyzeJarPlacement(assembly);
    near(result.neutralPointFt, expectedNeutral);
    expect(result.jars[0].issues).toEqual(expect.arrayContaining([expect.stringContaining('inside jar')]));
  });
});
